<?php $title=ucwords(str_replace('_',' ',$table));$heading=$title;$subheading='Direct records from aera. Changes are applied immediately.';ob_start(); ?>
<div class="toolbar"><form class="search-form" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search text fields..."><button class="btn btn-ghost">Search</button></form><a class="btn btn-gold" href="/admin/data/<?= e($table) ?>/new">+ New Record</a></div>
<div class="panel table-panel"><div class="table-scroll"><table class="data-table"><thead><tr><?php foreach($columns as $c): ?><th><?= e($c['Field']) ?></th><?php endforeach; ?><th class="actions-col">Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($columns as $c): $v=$row[$c['Field']]??null; ?><td title="<?= e(is_scalar($v)?$v:'') ?>"><?php if($v===null): ?><span class="null">NULL</span><?php else: ?><?= e(function_exists('mb_strimwidth') ? mb_strimwidth((string)$v,0,70,'…') : (strlen((string)$v)>70 ? substr((string)$v,0,67).'...' : (string)$v)) ?><?php endif; ?></td><?php endforeach; ?><td class="row-actions"><?php if($primary): ?><a href="/admin/data/<?= e($table) ?>/edit?key=<?= urlencode($row['_key']) ?>">Edit</a><form method="post" action="/admin/data/<?= e($table) ?>/delete" onsubmit="return confirm('Delete this record?');"><?= csrf_field() ?><input type="hidden" name="key" value="<?= e($row['_key']) ?>"><button type="submit">Delete</button></form><?php else: ?><span class="muted">No PK</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="<?= count($columns)+1 ?>" class="empty-cell">No records found.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="pagination"><?php if($page>1): ?><a href="?page=<?= $page-1 ?>&q=<?= urlencode($q) ?>">← Previous</a><?php endif; ?><span>Page <?= $page ?> of <?= $pages ?></span><?php if($page<$pages): ?><a href="?page=<?= $page+1 ?>&q=<?= urlencode($q) ?>">Next →</a><?php endif; ?></div>
<?php $content=ob_get_clean();require __DIR__.'/../../layouts/admin.php'; ?>
